sys_script.script:
(function executeRule(current, previous) {
    // Set defaults on insert
    if (current.operation() == 'insert') {
        current.setValue('status', 'booked');
    }

    // Block past service dates
    var serviceDate = current.getValue('service_date');
    if (serviceDate) {
        var today = new GlideDate();
        var sd = new GlideDate();
        sd.setValue(serviceDate);
        if (sd.compareTo(today) < 0) {
            gs.addErrorMessage('Service date cannot be in the past.');
            current.setAbortAction(true);
            return;
        }
    }

    // Limit active jobs per mechanic to 3 per day
    if (current.getValue('mechanic') && current.getValue('service_date')) {
        var count = new GlideAggregate('x_2220337_vehicl_0_svc_req');
        count.addQuery('mechanic', current.getValue('mechanic'));
        count.addQuery('service_date', current.getValue('service_date'));
        count.addQuery('status', 'IN', 'booked,in_service');
        if (!current.isNewRecord()) {
            count.addQuery('sys_id', '!=', current.getUniqueValue());
        }
        count.addAggregate('COUNT');
        count.query();
        if (count.next()) {
            var activeJobs = parseInt(count.getAggregate('COUNT'));
            if (activeJobs >= 3) {
                gs.addErrorMessage('This mechanic already has 3 active jobs on ' + current.getDisplayValue('service_date') + '. Please choose another mechanic or date.');
                current.setAbortAction(true);
                return;
            }
        }
    }

    // Set Premium customer priority to High
    if (current.getValue('customer')) {
        var cust = new GlideRecord('x_2220337_vehicl_0_customer');
        if (cust.get(current.getValue('customer'))) {
            if (cust.getValue('customer_type') == 'premium') {
                current.setValue('priority', '2');
            }
        }
    }

    // Close task on Delivered or Cancelled
    var statusVal = current.getValue('status');
    if (statusVal == 'delivered') {
        current.setValue('state', '3');
    } else if (statusVal == 'cancelled') {
        current.setValue('state', '4');
    }
})(current, previous);
